import requests

def predict(text, base_url):
    r = requests.post(f"{base_url}/predict", json={"text": text})
    return r.json()   # -> {'label', 'positive_probability', ...}

def discover_positive_words(sample_review, candidates, base_url):
    base_pos = predict(sample_review, base_url)['positive_probability']
    impacts = []
    for w in candidates:
        new_pos = predict(sample_review + " " + w, base_url)['positive_probability']
        impacts.append((w, new_pos - base_pos))   # positive push
    impacts.sort(key=lambda x: x[1], reverse=True)
    return [w for w, d in impacts if d > 0]

def flip_to_positive(review, good_words, base_url, budget=40):
    aug = review
    for w in good_words[:budget]:
        aug += " " + w
        if predict(aug, base_url)['label'] == 'positive':
            return aug
    return aug
